def load_table(path):
    with path.open() as f:
        reader=csv.DictReader(f,delimiter='\t')
        return list(reader.fieldnames),list(reader)


def fasta_records(path):
    header=None;lines=[]
    for line in path.open():
        if line.startswith('>'):
            if header is not None:yield header,''.join(lines)
            header=line[1:].strip();lines=[]
        elif line.strip():
            if header is None:raise ValueError('Sequence before FASTA header')
            lines.append(line.strip())
    if header is not None:yield header,''.join(lines)


def sha(path):
    h=hashlib.sha256()
    with path.open('rb') as f:
        for b in iter(lambda:f.read(4*1024*1024),b''):h.update(b)
    return h.hexdigest()


def write_table(path,fields,rows):
    with path.open('x') as f:
        w=csv.DictWriter(f,fieldnames=fields,delimiter='\t',extrasaction='ignore')
        w.writeheader();w.writerows(rows)


def finalize(a):
    review=a.root/'results/annotation_qc/08_TE_protein_review_v1'
    old=review/'first30_case_review_v1/first30.primary_case_review.tsv'
    source=review/'Scotti_TE_review.primary.tsv'
    allsource=review/'Scotti_TE_review.all_isoforms.tsv'
    candidate=a.root/'results/filtered_candidates/Scotti_filtered7_v1'
    fasta=candidate/'Scotti_nuclear.filtered7.longest.proteins.fa'
    out=a.out or review/'review100_v2'
    if out.exists():raise FileExistsError(f'Output already exists: {out}')
    fields,primary=load_table(source)
    _,previous=load_table(old)
    _,all_isoforms=load_table(allsource)
    assert len(primary)==a.expected_primary
    by_gene={r['gene_id']:r for r in primary}
    by_pid={r['protein_id']:r for r in primary}
    assert len(by_gene)==len(by_pid)==len(primary)
    assert len(all_isoforms)==a.expected_all_isoforms
    assert {r['gene_id'] for r in all_isoforms}==set(by_gene)
    assert len(previous)==30
    case={}
    for r in previous:
        if r['case_review_category']=='strong_TE_associated_candidate':
            case[r['gene_id']]=dict(category='strong_TE_associated_candidate',
                reason=r['case_review_reason'],action='include_in_conservative_TE_exclusion_comparison')
        elif r['case_review_category']=='cellular_function_supported':
            case[r['gene_id']]=dict(category='cellular_function_supported',
                reason=r['case_review_reason'],action='retain_in_current_proteome')
    assert len(case)==16
    assert not set(case)&set(NEXT84)
    case.update(NEXT84)
    assert len(case)==100
    selected=[r for r in primary if r['review_tier'] in {
        'priority_functional_review','functional_candidate_review','host_context_review'}]
    assert {r['gene_id'] for r in selected}==set(case)
    for gene,d in NEXT84.items():
        r=by_gene[gene]
        assert r['protein_id']==d['protein_id'],gene
        assert int(r['length_aa'])==d['length_aa'],gene
        assert abs(float(r['CDS_RM_classified_TE_pct'])-d['classified_TE_pct'])<.0001,gene
        assert abs(float(r['CDS_RM_unknown_pct'])-d['unknown_pct'])<.0001,gene
    records=list(fasta_records(fasta))
    ids=[h.split()[0] for h,s in records]
    assert len(ids)==len(set(ids))==len(primary)
    assert set(ids)==set(by_pid)
    for header,seq in records:
        assert len(seq.rstrip('*'))==int(by_pid[header.split()[0]]['length_aa'])

    extra=['case_review_category_v2','review_group_v2','provisional_action_v2','case_review_reason_v2']
    reviewed=[]
    for r in selected:
        d=case[r['gene_id']]
        group=('strong_TE_candidate' if d['category']=='strong_TE_associated_candidate'
               else 'retain_TE_not_supported' if d['category'] in RETAIN_CATEGORIES
               else 'unresolved_keep_in_comparison')
        row=dict(r)
        row.update(zip(extra,[d['category'],group,d['action'],d['reason']]))
        reviewed.append(row)
    groups=Counter(r['review_group_v2'] for r in reviewed)
    assert groups=={'strong_TE_candidate':32,'retain_TE_not_supported':21,'unresolved_keep_in_comparison':47},groups
    drop={r['protein_id'] for r in reviewed if r['review_group_v2']=='strong_TE_candidate'}
    drop_genes={by_pid[p]['gene_id'] for p in drop}
    out.mkdir(parents=True)
    write_table(out/'Scotti_TE.primary_case_review100.v2.tsv',fields+extra,reviewed)
    for group in groups:
        subset=[r for r in reviewed if r['review_group_v2']==group]
        write_table(out/f'{group}.review.tsv',fields+extra,subset)
        (out/f'{group}.primary_ids.txt').write_text(''.join(r['protein_id']+'\n' for r in subset))
    # 9,134 proteins outside this review are explicitly unreviewed here, not certified nonTE.
    all_rows=[];review_by_pid={r['protein_id']:r for r in reviewed}
    for r in primary:
        row=dict(r)
        if r['protein_id'] in review_by_pid:row.update(review_by_pid[r['protein_id']])
        else:row.update(dict(zip(extra,['not_in_functional_screen_case_set','not_case_reviewed','retain_no_case_decision','No case-specific TE decision was made for this model.'])))
        all_rows.append(row)
    write_table(out/'Scotti_primary.all_review_status.v2.tsv',fields+extra,all_rows)
    # Preserve all isoforms for the strong candidate genes for separate architecture review.
    iso=[r for r in all_isoforms if r['gene_id'] in drop_genes]
    write_table(out/'strong32.all_isoform_context.tsv',list(all_isoforms[0]),iso)
    alternative_without_screen={r['gene_id'] for r in iso
        if r['protein_id'] not in drop and r['review_tier']=='no_screening_signal'}
    comparison_count=None
    if a.build_comparison:
        kept=out/'Scotti_primary.without32_strong_TE_candidates.sensitivity.faa'
        excluded=out/'Scotti_primary.strong32_TE_candidates.faa'
        n_keep=n_drop=0
        with kept.open('x') as k,excluded.open('x') as d:
            for header,seq in records:
                pid=header.split()[0]
                handle=d if pid in drop else k
                if pid in drop:n_drop+=1
                else:n_keep+=1
                handle.write('>'+header+'\n')
                for i in range(0,len(seq),80):handle.write(seq[i:i+80]+'\n')
        assert n_keep==a.expected_primary-32 and n_drop==32
        comparison_count=n_keep
    summary=dict(status='provisional_TE_review_sensitivity_not_final_annotation',
        source_primary_proteins=len(primary),case_reviewed_primary_proteins=100,
        review_groups=dict(groups),unreviewed_in_this_case_set=len(primary)-100,
        sensitivity_comparison_created=a.build_comparison,
        sensitivity_retained_primary_proteins=comparison_count,
        annotation_GFF_or_CDS_changed=False,source_proteins_changed=False,
        strong_candidate_gene_isoforms_exported=len(iso),
        strong_genes_with_alternative_isoform_without_screening_signal=sorted(alternative_without_screen),
        case_categories=dict(Counter(r['case_review_category_v2'] for r in reviewed)))
    (out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
    (out/'README.txt').write_text(
        'Scotti case review of 100 functionally screened PRIMARY proteins. Provisional case-specific calls; no source genome, GFF, CDS or protein files were changed.\n'
        '32 strong TE-associated candidates, 21 cellular/shared-domain cases provisionally retained, 47 unresolved cases retained in the conservative comparison. This does NOT mean the entire proteome has been certified free of TE proteins.\n'
        'Candidate calls combine the supplied descriptions, direct member-domain evidence and CDS repeat coverage. eggNOG PFAM names are transferred annotation, not direct query-domain calls. A broad structural superfamily, integrase-binding domain, CCHC zinc finger or DDI1-like protease alone does not establish TE origin.\n'
        'The optional sensitivity FASTA omits only the 32 listed PRIMARY protein records. It is not a final nonTE proteome or a new annotation release, and it does not modify other species or freeze a new OrthoFinder input. The original longest protein IDs and sequences are preserved; no substitute isoforms are selected. All isoforms of the 32 strong candidate genes are exported as evidence for later review.\n'
        'TE candidates may be fragments or cellular/domesticated derivatives; this review does not establish active transposition. Mixed models and conflicting cellular/repeat cases remain unresolved. The 47 unresolved proteins remain in the sensitivity set.\n'
        'RepeatMasker classified-TE and Unknown coverages are independent interval unions and may overlap each other; do not add the percentages. No new RNA-support test, manual locus inspection, domain search, or final contamination screen was performed here.\n'
        'Status table covers the complete primary proteome, with the other proteins marked not_case_reviewed. Repeat-only/generic initial screen tiers were not promoted automatically to TE status. Uniform cross-species TE treatment remains a separate comparative-analysis step.\n')
    shutil.copy2(Path(__file__),out/'finalize_scotti_te_case_review.py')
    with (out/'input.SHA256SUMS').open('x') as f:
        for path in [source,old,allsource,fasta]:f.write(f'{sha(path)}  {path}\n')
    with (out/'SHA256SUMS').open('x') as f:
        for path in sorted(out.iterdir()):
            if path.is_file() and path.name!='SHA256SUMS':f.write(f'{sha(path)}  {path.name}\n')
    print(json.dumps(summary,indent=2));print('Output:',out)


def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--root',type=Path,default=Path('/work/cyu/annotation/scotti-annotation'))
    p.add_argument('--out',type=Path)
    p.add_argument('--build-comparison',action='store_true')
    p.add_argument('--expected-primary',type=int,default=9234)
    p.add_argument('--expected-all-isoforms',type=int,default=11464)
    finalize(p.parse_args())

if __name__=='__main__':main()
